-- Full SEO & GEO 100/100 content, metadata, category buying guides, landing page tables, FAQs, and bespoke product copy.
-- Every UPDATE checks MD5() or empty-field conditions so custom shop edits made in Admin are never overwritten.

ALTER TABLE `categories` ADD COLUMN `guide` mediumtext DEFAULT NULL AFTER `description`;

-- Category metadata length fixes
UPDATE `categories` SET `meta_title` = 'Red Velvet & Velvet Cakes Canberra | Continental Cake Shop'
  WHERE `slug` = 'velvet-cakes' AND `meta_title` = 'Red Velvet & Velvet Cakes Canberra | The Continental Cake Shop';
UPDATE `categories` SET `meta_description` = 'Rich 100% Halal chocolate, white gold, marble and caramel mud cakes baked fresh in Greenway. Order online for Canberra pickup or delivery.'
  WHERE `slug` = 'mud-cakes' AND `meta_description` = 'Chocolate, white gold, marble and caramel mud cakes made fresh in Canberra. Order online and pick up in Greenway.';
UPDATE `categories` SET `meta_description` = 'Fresh 100% Halal carrot cake, orange poppy seed cake, pavlova and profiterole towers baked in Greenway for Canberra pickup or delivery.'
  WHERE `slug` = 'tea-cakes-desserts' AND `meta_description` = 'Carrot cake, pavlova and profiterole towers from The Continental Cake Shop in Greenway, Canberra.';

-- Category buying guides (420+ words + comparative HTML tables)
UPDATE `categories` SET `guide` = '<h2>What Is a European Sponge Torte — and Why Canberra Families Choose Them</h2>\n<p>A torte at {store_name} is a multi-layered European-style sponge cake brushed lightly for moisture and filled with whipped continental cream, fruit compotes, roasted nuts, espresso or airy mousse. Unlike heavy fondant or dense butter cakes, our tortes slice cleanly with a gentle, cloud-light crumb that is balanced rather than overly sweet—making them our most requested birthday and family dinner cakes in Greenway since March 2015.</p>\n<p>Every torte in our Tuggeranong kitchen is baked from scratch using <strong>100% Halal ingredients</strong>, with zero alcohol or liqueurs (including our espresso-soaked <a href=\"{url:cakes/tiramisu-torte}\">Tiramisu Torte</a> and sour-cherry <a href=\"{url:cakes/black-forest-torte}\">Black Forest Torte</a>), no animal shortening, and only Halal-suitable gelatine and vanilla.</p>\n<h3>Compare Our Most Popular Canberra Tortes</h3>\n<table>\n<thead><tr><th scope=\"col\">Torte Flavour</th><th scope=\"col\">Sponge &amp; Filling Profile</th><th scope=\"col\">Available Sizes</th><th scope=\"col\">Best For</th></tr></thead>\n<tbody>\n<tr><td><a href=\"{url:cakes/black-forest-torte}\"><strong>Black Forest Torte</strong></a></td><td>Dark cocoa sponge, whipped vanilla cream, tart cherries &amp; chocolate shavings</td><td>Midi (8) · Full (14)</td><td>Classic birthdays &amp; cherry-chocolate fans</td></tr>\n<tr><td><a href=\"{url:cakes/tiramisu-torte}\"><strong>Tiramisu Torte</strong></a></td><td>Alcohol-free espresso-brushed sponge, creamy mascarpone-style filling &amp; cocoa</td><td>Full (14)</td><td>Coffee lovers &amp; dinner parties</td></tr>\n<tr><td><a href=\"{url:cakes/continental-torte}\"><strong>Continental Torte</strong></a></td><td>Signature house sponge layered with smooth continental cream &amp; custard notes</td><td>Midi (8) · Full (14)</td><td>Multi-generational family celebrations</td></tr>\n<tr><td><a href=\"{url:cakes/rainbow-torte}\"><strong>Rainbow Torte</strong></a></td><td>Vibrant six-colour sponge layers with fresh cream rosettes</td><td>Large (14) · XL (20)</td><td>Kids\' birthdays &amp; school celebrations</td></tr>\n<tr><td><a href=\"{url:cakes/honey-bee-torte}\"><strong>Honey-Bee Torte</strong></a></td><td>Three honey-baked sponge layers with continental cream &amp; vanilla custard</td><td>Midi (8) · Full (14)</td><td>Afternoon teas &amp; gentle sweetness</td></tr>\n</tbody>\n</table>\n<h3>How Many Guests Do Midi, Full &amp; XL Tortes Serve?</h3>\n<p>Choose a <strong>Midi torte (serves ~8)</strong> for intimate family dinners, a <strong>Full torte (serves ~14)</strong> for birthday parties and office morning teas, or our <strong>XL Rainbow Torte (serves ~20)</strong> for larger crowds. Every torte includes a <strong>free piped message</strong> on top—just add your wording before checkout.</p>\n<h3>Ordering, Dietary Options &amp; Fridge Storage</h3>\n<p>Order online with at least {min_lead_hours} hours notice for free pickup at {store_address} or scheduled delivery across Canberra and Queanbeyan. Eggless, vegan and gluten-free torte variations can be arranged on request—call {store_phone} before ordering and review our <a href=\"{url:allergens}\">allergen guide</a>. Because our tortes are filled with fresh dairy cream, transport the box flat on your car floor and store refrigerated at 2–5°C for up to 3 days.</p>' WHERE `slug` = 'tortes' AND (`guide` IS NULL OR `guide` = '');
UPDATE `categories` SET `guide` = '<h2>Fresh Red Velvet &amp; Velvet Cakes Baked in Greenway, Canberra</h2>\n<p>Our velvet cakes pair a tender, fine-crumb cocoa-kissed sponge with generous layers of smooth, tangy cream cheese frosting finished by hand in our Greenway kitchen. That subtle tang cuts through the sweetness so every slice feels balanced and velvety—making <a href=\"{url:cakes/red-velvet-cake}\">Red Velvet Cake</a> one of Canberra\'s favourite centrepieces for engagements, anniversaries, Eid tables and milestone birthdays.</p>\n<p>Like everything baked at {store_name} since March 2015, our velvet cakes are made with <strong>100% Halal ingredients</strong>—zero alcohol, no animal fats, and Halal-suitable vanilla and food colourings—so every guest at your celebration can enjoy a slice with confidence.</p>\n<h3>Velvet Cake Sizes, Servings &amp; Ordering Details</h3>\n<table>\n<thead><tr><th scope=\"col\">Size</th><th scope=\"col\">Approximate Guests</th><th scope=\"col\">Frosting &amp; Finish</th><th scope=\"col\">Minimum Notice</th></tr></thead>\n<tbody>\n<tr><td><strong>Midi Velvet Cake</strong></td><td>Serves ~8 dessert portions</td><td>Hand-smoothed cream cheese frosting + free piped message</td><td>{min_lead_hours} hours online</td></tr>\n<tr><td><strong>Full Velvet Cake</strong></td><td>Serves ~14 dessert portions</td><td>Tall layered velvet sponge, cream cheese icing + free message</td><td>{min_lead_hours} hours online</td></tr>\n<tr><td><strong>Custom Tiered Velvet Cake</strong></td><td>14 to 120+ guests</td><td>Bespoke <a href=\"{url:custom-cakes}\">wedding or engagement design</a>, florals or vintage piping</td><td>{custom_lead_days} days (2–8 wks for tiered)</td></tr>\n</tbody>\n</table>\n<h3>When to Choose Velvet Cake Over a Sponge Torte or Mud Cake</h3>\n<ul>\n<li><strong>Choose a Velvet Cake</strong> when you want a plush, medium-density crumb paired with tangy cream cheese frosting that holds clean slices for photos and candle-blowing.</li>\n<li><strong>Choose a <a href=\"{url:shop/tortes}\">European Torte</a></strong> if your guests prefer airy whipped cream and fresh fruit layers.</li>\n<li><strong>Choose a <a href=\"{url:shop/mud-cakes}\">Mud Cake</a></strong> when you want deep fudgy chocolate richness or a sculpted multi-tier cake that travels long distances in warm weather.</li>\n</ul>\n<h3>Storage, Transport &amp; Dietary Requests in Canberra</h3>\n<p>Order online for timed pickup in Greenway or courier delivery across Tuggeranong, Woden, Molonglo Valley, Belconnen, Gungahlin, Inner Canberra and Queanbeyan. Keep cream-cheese frosted velvet cakes chilled at 2–5°C and take the cake out of the fridge 20 minutes before cutting so the crumb softens to peak tenderness. For eggless options or custom colour themes, call {store_phone} or check our <a href=\"{url:allergens}\">allergen information</a>.</p>' WHERE `slug` = 'velvet-cakes' AND (`guide` IS NULL OR `guide` = '');
UPDATE `categories` SET `guide` = '<h2>Rich 100% Halal Mud Cakes in Canberra — Built for Flavour &amp; Celebrations</h2>\n<p>Baked slow and low in our Greenway ovens, our mud cakes have a moist, fudgy crumb and glossy ganache finish that chocolate and caramel lovers come back for year after year. Because mud cake batter is naturally dense and sturdy, it holds sharp edges, travels reliably in the car across Canberra and Queanbeyan, and serves generous finger or dessert slices without crumbling.</p>\n<p>Every mud cake at {store_name} is made from scratch using <strong>100% Halal ingredients</strong>—real cocoa, white and dark couverture-style chocolate notes, butter/vegetable blends with zero animal shortening, and zero alcohol. Free custom writing is piped onto every Midi and Full mud cake at no extra charge.</p>\n<h3>Compare Our Five Signature Canberra Mud Cakes</h3>\n<table>\n<thead><tr><th scope=\"col\">Mud Cake</th><th scope=\"col\">Flavour Profile</th><th scope=\"col\">Sizes &amp; Servings</th><th scope=\"col\">Ideal Occasion</th></tr></thead>\n<tbody>\n<tr><td><a href=\"{url:cakes/chocolate-mud-cake}\"><strong>Chocolate Mud Cake</strong></a></td><td>Deep, fudgy dark cocoa crumb coated in smooth chocolate ganache</td><td>Midi (8) · Full (14)</td><td>All-ages birthdays, chocoholics &amp; party travel</td></tr>\n<tr><td><a href=\"{url:cakes/white-gold-mud-cake}\"><strong>White Gold Mud Cake</strong></a></td><td>Creamy white chocolate mud crumb with a warm caramelised note</td><td>Midi (8) · Full (14)</td><td>Engagements, milestone birthdays &amp; white-chocolate fans</td></tr>\n<tr><td><a href=\"{url:cakes/marble-mud-cake}\"><strong>Marble Mud Cake</strong></a></td><td>Swirled ribbons of vanilla and dark chocolate mud batter</td><td>Midi (8) · Full (14)</td><td>Mixed-crowd offices, kids\' parties &amp; family gatherings</td></tr>\n<tr><td><a href=\"{url:cakes/caramel-mud-cake}\"><strong>Caramel Mud Cake</strong></a></td><td>Buttery golden caramel mud crumb with smooth caramel glaze</td><td>Midi (8) · Full (14)</td><td>Autumn/winter dinners &amp; salted/sweet caramel lovers</td></tr>\n<tr><td><a href=\"{url:cakes/treasure-cake}\"><strong>Treasure Cake</strong></a></td><td>Signature loaded mud cake crowned with assorted chocolates &amp; treats</td><td>Midi (8) · Full (14)</td><td>Showstopper teen &amp; adult birthday centrepiece</td></tr>\n</tbody>\n</table>\n<h3>Gluten-Free Mud Cakes, Serving Tips &amp; Custom Tiers</h3>\n<p>Mud cakes are also our number-one structural base for <a href=\"{url:wedding-cakes-canberra}\">tiered wedding cakes</a> and themed <a href=\"{url:custom-cakes}\">custom birthday cakes</a>. <strong>Gluten-free mud cakes</strong> can be baked on request—call {store_phone} before ordering to confirm availability, and review our <a href=\"{url:allergens}\">allergen page</a> regarding shared kitchen traces. For the fudgiest texture, store refrigerated and stand your mud cake at room temperature for 30–45 minutes before slicing with a warm knife wiped clean between cuts.</p>' WHERE `slug` = 'mud-cakes' AND (`guide` IS NULL OR `guide` = '');
UPDATE `categories` SET `guide` = '<h2>Classic Oven-Baked Cheesecakes in Canberra — Full &amp; Half Sizes</h2>\n<p>Our oven-baked cheesecakes follow the timeless New York and European patisserie tradition: rich cream cheese blended smooth with eggs and vanilla over a buttery crushed-biscuit crust, baked gently until velvety from edge to centre. Whether you need a <strong>Half cheesecake (serves ~6)</strong> for a weeknight family dessert or a <strong>Full cheesecake (serves ~12)</strong> for an office morning tea or birthday spread, every cheesecake is baked fresh in our Greenway shop.</p>\n<p>All five flavours use <strong>100% Halal ingredients</strong> with zero alcohol and no animal shortening, making them effortless to share across workplaces, schools and family tables throughout Canberra and Queanbeyan.</p>\n<h3>Compare Our Oven-Baked Cheesecake Range</h3>\n<table>\n<thead><tr><th scope=\"col\">Baked Cheesecake</th><th scope=\"col\">Topping &amp; Flavour Notes</th><th scope=\"col\">Sizes</th><th scope=\"col\">Pairing Suggestion</th></tr></thead>\n<tbody>\n<tr><td><a href=\"{url:cakes/american-baked-cheesecake}\"><strong>American Baked Cheesecake</strong></a></td><td>Classic golden New York style vanilla cream cheese on biscuit base</td><td>Half (6) · Full (12)</td><td>Espresso, fresh berries or enjoyed plain</td></tr>\n<tr><td><a href=\"{url:cakes/blueberry-baked-cheesecake}\"><strong>Blueberry Baked Cheesecake</strong></a></td><td>Velvety baked cream cheese crowned with glossy whole-berry compote</td><td>Half (6) · Full (12)</td><td>Afternoon tea &amp; Sunday family lunches</td></tr>\n<tr><td><a href=\"{url:cakes/marble-baked-cheesecake}\"><strong>Marble Baked Cheesecake</strong></a></td><td>Creamy vanilla cheesecake rippled with rich dark chocolate swirls</td><td>Half (6) · Full (12)</td><td>Dinner parties &amp; chocolate-cheesecake fans</td></tr>\n<tr><td><a href=\"{url:cakes/tropical-baked-cheesecake}\"><strong>Tropical Baked Cheesecake</strong></a></td><td>Dense baked cheesecake brightened with sunny tropical fruit glaze</td><td>Half (6) · Full (12)</td><td>Summer barbecues &amp; festive grazing tables</td></tr>\n<tr><td><a href=\"{url:cakes/hazelnut-baked-cheesecake}\"><strong>Hazelnut Baked Cheesecake</strong></a></td><td>Roasted hazelnut &amp; cocoa notes folded through baked cream cheese</td><td>Half (6) · Full (12)</td><td>After-dinner coffee &amp; nut-chocolate lovers</td></tr>\n</tbody>\n</table>\n<h3>Baked Cheesecake vs. Continental Cheesecake — Which Should You Pick?</h3>\n<p>Choose an <strong>oven-baked cheesecake</strong> when you love a dense, rich, custard-smooth texture that pairs beautifully with hot coffee. Prefer something chilled, airy and mousse-light after a heavy meal? Explore our <a href=\"{url:shop/continental-cheesecakes}\">Continental Cheesecakes</a>. Order online at least {min_lead_hours} hours ahead for pickup at {store_address} or delivery across Canberra. Keep refrigerated at 2–5°C and slice with a hot, dry blade for café-clean wedges.</p>' WHERE `slug` = 'baked-cheesecakes' AND (`guide` IS NULL OR `guide` = '');
UPDATE `categories` SET `guide` = '<h2>Light, Chilled Continental Cheesecakes in Canberra — Full &amp; Half Sizes</h2>\n<p>A Canberra staple for summer entertaining, Iftar gatherings and post-roast family desserts, our <strong>continental cheesecakes</strong> are chilled, mousse-light cream cheese cakes set atop a crisp biscuit crumb without heavy oven baking. Each bite is cool, delicate and refreshing—ideal for guests who find mud cakes or New York baked cheesecakes too rich after a big meal.</p>\n<p>Crucially for Halal households across Canberra, every continental cheesecake at {store_name} is set exclusively with <strong>100% Halal-suitable ingredients</strong> (zero pork gelatine, zero alcohol and no animal shortening), prepared fresh inside our dedicated Halal Greenway kitchen.</p>\n<h3>Compare Our Six Continental Cheesecake Flavours</h3>\n<table>\n<thead><tr><th scope=\"col\">Continental Cheesecake</th><th scope=\"col\">Flavour &amp; Finish</th><th scope=\"col\">Sizes &amp; Servings</th><th scope=\"col\">Best Occasion</th></tr></thead>\n<tbody>\n<tr><td><a href=\"{url:cakes/strawberry-cheesecake}\"><strong>Strawberry Cheesecake</strong></a></td><td>Airy set cream cheese finished with sweet strawberry glaze</td><td>Half (6) · Full (12)</td><td>Family birthdays, picnics &amp; kids\' favourites</td></tr>\n<tr><td><a href=\"{url:cakes/passionfruit-cheesecake}\"><strong>Passionfruit Cheesecake</strong></a></td><td>Light mousse-style cheesecake with tangy passionfruit seed topping</td><td>Half (6) · Full (12)</td><td>Summer lunches, barbecues &amp; citrus/fruit lovers</td></tr>\n<tr><td><a href=\"{url:cakes/tangy-lemon-cheesecake}\"><strong>Tangy Lemon Cheesecake</strong></a></td><td>Crisp, zesty lemon finish over cool whipped cream cheese</td><td>Half (6) · Full (12)</td><td>Refreshing palate cleanser after rich banquets</td></tr>\n<tr><td><a href=\"{url:cakes/blueberry-cheesecake}\"><strong>Blueberry Cheesecake</strong></a></td><td>Smooth continental cream cheese topped with vibrant blueberry compote</td><td>Half (6) · Full (12)</td><td>Morning teas &amp; weekend family visits</td></tr>\n<tr><td><a href=\"{url:cakes/caramel-cheesecake}\"><strong>Caramel Cheesecake</strong></a></td><td>Silky caramel crown over light continental cheesecake &amp; biscuit base</td><td>Half (6) · Full (12)</td><td>Sweet-tooth dessert tables &amp; office shout</td></tr>\n<tr><td><a href=\"{url:cakes/choc-chip-cheesecake}\"><strong>Choc Chip Cheesecake</strong></a></td><td>Whipped continental filling speckled with crisp chocolate chips</td><td>Half (6) · Full (12)</td><td>Kids\' dinners &amp; casual weekend treats</td></tr>\n</tbody>\n</table>\n<h3>Ordering, Pickup, Canberra Delivery &amp; Chilled Storage</h3>\n<p>Available in <strong>Half (serves ~6, from $22.95)</strong> and <strong>Full (serves ~12, from $39.95)</strong> with just {min_lead_hours} hours online notice. Pick up from {store_address} or book delivery across Canberra and Queanbeyan at checkout. Keep chilled continental cheesecakes in the refrigerator at 2–5°C right until serving, and check our <a href=\"{url:allergens}\">allergen guide</a> or call {store_phone} if ordering for guests with food sensitivities.</p>' WHERE `slug` = 'continental-cheesecakes' AND (`guide` IS NULL OR `guide` = '');
UPDATE `categories` SET `guide` = '<h2>Fresh Tea Cakes, Pavlova &amp; Profiterole Towers in Canberra</h2>\n<p>Beyond layered tortes and cheesecakes, our Greenway pastry team bakes classic Australian morning-tea cakes and showstopping French-inspired dessert centrepieces—all made with <strong>100% Halal ingredients</strong>, zero alcohol and fresh local dairy. Whether you are hosting an office morning tea in Woden or Barton, bringing a gift to a Tuggeranong family lunch, or styling an engagement grazing table, these four favourites arrive ready to serve.</p>\n<h3>Compare Our Tea Cakes &amp; Dessert Centrepieces</h3>\n<table>\n<thead><tr><th scope=\"col\">Dessert / Tea Cake</th><th scope=\"col\">Style &amp; Texture</th><th scope=\"col\">Sizes &amp; Servings</th><th scope=\"col\">Best Occasion</th></tr></thead>\n<tbody>\n<tr><td><a href=\"{url:cakes/profiterole-tower}\"><strong>Profiterole Tower</strong></a></td><td>Golden choux pastry puffs filled with fresh cream &amp; drizzled with chocolate</td><td>20, 25, 30 or 35 pieces (serves ~10–18)</td><td>Engagements, milestone birthdays &amp; corporate events</td></tr>\n<tr><td><a href=\"{url:cakes/pavlova}\"><strong>Pavlova</strong></a></td><td>Crisp baked meringue shell, pillowy marshmallow centre, whipped cream &amp; fresh fruit</td><td>One size (serves ~10)</td><td>Australian summer lunches, Eid, Christmas &amp; gluten-friendly tables*</td></tr>\n<tr><td><a href=\"{url:cakes/carrot-cake}\"><strong>Carrot Cake</strong></a></td><td>Moist warmly spiced grated-carrot sponge topped with smooth cream cheese icing</td><td>Midi (8) · Full (14)</td><td>Office morning teas, birthdays &amp; afternoon coffee</td></tr>\n<tr><td><a href=\"{url:cakes/orange-poppy-seed-cake}\"><strong>Orange &amp; Poppy Seed Cake</strong></a></td><td>Fragrant citrus tea cake speckled with crunchy blue poppy seeds &amp; icing</td><td>Midi (8) · Full (14)</td><td>Morning tea platters, brunch &amp; thank-you gifts</td></tr>\n</tbody>\n</table>\n<h3>Tips for Serving Profiterole Towers, Pavlova &amp; Tea Cakes</h3>\n<ul>\n<li><strong>Profiterole Towers:</strong> Guests can lift individual cream-filled choux puffs straight from the tower—no knife or plates needed at stand-up cocktail parties and office functions.</li>\n<li><strong>Pavlova &amp; Cream-Topped Cakes:</strong> Store refrigerated at 2–5°C and serve on the day of pickup or within 24–48 hours while the meringue shell stays crisp.</li>\n<li><strong>Allergen Note (*):</strong> While pavlova meringue is naturally made without wheat flour, our Greenway kitchen handles wheat, dairy, eggs, soy and tree nuts—please read our <a href=\"{url:allergens}\">allergen information</a> or call {store_phone} before ordering.</li>\n</ul>\n<p>Order online at least {min_lead_hours} hours ahead for pickup in Greenway or delivery across Canberra and Queanbeyan, or <a href=\"{url:custom-cakes}\">enquire about a larger custom profiterole tower or dessert spread</a>.</p>' WHERE `slug` = 'tea-cakes-desserts' AND (`guide` IS NULL OR `guide` = '');

-- Allergens policy page metadata & quick-reference matrix
UPDATE `pages` SET `meta_description` = 'Allergen, 100% Halal, gluten-free, eggless and vegan cake information from our Greenway kitchen in Canberra. Check ingredients before ordering.' WHERE `slug` = 'allergens' AND (`meta_description` IS NULL OR `meta_description` = '');
UPDATE `pages` SET `body` = '<p>Your safety and dietary confidence matter to us. Please read this guide before ordering if you or your guests have a food allergy, intolerance or religious dietary requirement.</p>\n<h2>Our Greenway Kitchen &amp; Cross-Contact Notice</h2>\n<p>Every cake at {store_name} is baked by hand in our kitchen at {store_address}, which handles common allergens daily—including <strong>milk (dairy)</strong>, <strong>eggs</strong>, <strong>wheat (gluten)</strong>, <strong>soy</strong> and <strong>tree nuts</strong> (hazelnuts, almonds, walnuts and pistachios). Because we share ovens, mixers and preparation benches, <strong>we cannot guarantee that any product is 100% free from traces of allergens</strong> for individuals with severe or anaphylactic allergies.</p>\n<h2>Dietary, Allergen &amp; Halal Quick-Reference Guide</h2>\n<table>\n<thead><tr><th scope=\"col\">Dietary / Ingredient Question</th><th scope=\"col\">Status in Our Kitchen</th><th scope=\"col\">How to Order Safely</th></tr></thead>\n<tbody>\n<tr><td><strong>100% Halal Ingredients</strong></td><td>Yes — 100% of products across the entire shop</td><td>Standard on every menu &amp; custom cake (zero alcohol, no animal shortening, Halal-suitable gelatine)</td></tr>\n<tr><td><strong>Alcohol / Liqueurs</strong></td><td>0% alcohol used anywhere in our kitchen</td><td>Even our <a href=\"{url:cakes/tiramisu-torte}\">Tiramisu</a> &amp; <a href=\"{url:cakes/black-forest-torte}\">Black Forest</a> tortes are completely alcohol-free</td></tr>\n<tr><td><strong>Eggless Cakes</strong></td><td>Available on eligible cakes &amp; custom orders</td><td>Tick <em>Eggless</em> on eligible product pages or call {store_phone} before ordering</td></tr>\n<tr><td><strong>Gluten-Free Options</strong></td><td>Made on request (including selected <a href=\"{url:shop/mud-cakes}\">mud cakes</a>)</td><td>Call {store_phone} prior to ordering; prepared in a kitchen that also handles wheat flour</td></tr>\n<tr><td><strong>Vegan Options</strong></td><td>Available on request for custom orders</td><td>Call {store_phone} or note on our <a href=\"{url:custom-cakes}\">custom cake quote form</a></td></tr>\n<tr><td><strong>Tree Nuts, Dairy &amp; Soy</strong></td><td>Present in recipes &amp; shared kitchen equipment</td><td>Ask our team about nut-free recipes; trace cross-contact cannot be ruled out</td></tr>\n</tbody>\n</table>\n<h2>Ask Our Bakers Before You Order</h2>\n<p>If you have questions about a specific sponge, glaze, biscuit base or edible topper, please call us on {store_phone} or ask in store before placing your order, and include any allergy notes in the checkout comments so our kitchen team sees them clearly on your baking sheet.</p>' WHERE `slug` = 'allergens' AND MD5(`body`) = '2e433bafec9b5c8cd730fb5de2dad8a6';

-- Canberra occasion landing pages (answer-first passages, tables & SVG portion/tier guides)
UPDATE `pages` SET `body` = '<h2>Are All Cakes at The Continental Cake Shop 100% Halal?</h2>\n<p>Yes — every cake, European sponge torte, mud cake, velvet cake, cheesecake and dessert baked at {store_name} in Greenway, Tuggeranong is made exclusively with <strong>100% Halal ingredients</strong>. Because our entire Canberra kitchen operates to a strict Halal-only ingredient standard since opening in March 2015 (rather than baking a small separate Halal line alongside non-Halal products), there is zero cross-contact with alcohol, liqueurs, pork-derived gelatine or animal shortening.</p>\n<h3>Our 100% Halal Kitchen Ingredient Standards</h3>\n<table>\n<thead><tr><th scope=\"col\">Ingredient Category</th><th scope=\"col\">Our Greenway Kitchen Standard</th><th scope=\"col\">Applies To</th></tr></thead>\n<tbody>\n<tr><td><strong>Gelatine &amp; Setting Agents</strong></td><td>100% Halal-suitable gelatine &amp; plant-based setting agents only (zero porcine gelatine)</td><td>All <a href=\"{url:shop/continental-cheesecakes}\">Continental Cheesecakes</a> &amp; mousse tortes</td></tr>\n<tr><td><strong>Alcohol &amp; Liqueurs</strong></td><td>Strictly 0% alcohol — espresso &amp; fruit syrups used instead of coffee/cherry liqueurs</td><td><a href=\"{url:cakes/tiramisu-torte}\">Tiramisu Torte</a>, <a href=\"{url:cakes/black-forest-torte}\">Black Forest Torte</a> &amp; entire menu</td></tr>\n<tr><td><strong>Fats, Emulsifiers &amp; Dairy</strong></td><td>Fresh Australian dairy cream, butter &amp; Halal-suitable vegetable oils (zero lard/tallow)</td><td>All sponges, <a href=\"{url:shop/mud-cakes}\">Mud Cakes</a>, choux pastry &amp; frostings</td></tr>\n<tr><td><strong>Vanilla, Colours &amp; Toppings</strong></td><td>Halal-suitable vanilla flavourings, cocoa, chocolates &amp; edible image inks</td><td>All ready-made &amp; <a href=\"{url:custom-cakes}\">Custom Celebration Cakes</a></td></tr>\n</tbody>\n</table>\n<h2>Halal Cakes for Eid, Nikah, Weddings, Birthdays &amp; Office Events</h2>\n<p>Whether you need a last-minute cake for Iftar or an office farewell in Woden, Barton or Civic, or a tiered centrepiece for a Nikah, Walima, Aqiqah or milestone birthday, you can order two ways:</p>\n<ul>\n<li><strong>Ready-to-order menu cakes ({min_lead_hours} hours notice):</strong> Choose from 34+ <a href=\"{url:shop/tortes}\">tortes</a>, <a href=\"{url:shop/mud-cakes}\">mud cakes</a>, <a href=\"{url:shop/velvet-cakes}\">velvet cakes</a>, <a href=\"{url:shop/baked-cheesecakes}\">baked cheesecakes</a>, <a href=\"{url:shop/continental-cheesecakes}\">continental cheesecakes</a> and <a href=\"{url:cakes/profiterole-tower}\">profiterole towers</a> from $22.95, with free custom piped writing included on celebration cakes.</li>\n<li><strong>Custom &amp; tiered celebration cakes (at least {custom_lead_days} days notice; 2–8+ weeks for <a href=\"{url:wedding-cakes-canberra}\">wedding cakes</a>):</strong> Send a reference photo via our <a href=\"{url:custom-cakes}\">custom cake quote form</a> for custom buttercream, vintage piping, edible images or multi-tier designs.</li>\n</ul>\n<img src=\"{url:assets/img/cake-serving-guide.svg}\" alt=\"Halal cake sizes and serving guide in Canberra: Half Cheesecake serves 6, Midi serves 8, Full Cheesecake serves 12, Full Cake serves 14, XL and Towers serve 15 to 20\" width=\"960\" height=\"340\">\n<h2>Eggless, Vegan, Gluten-Free &amp; Allergen Transparency</h2>\n<p>Many Canberra celebrations include guests with extra dietary requirements. Select <strong>Eggless</strong> directly on eligible cake pages, or call {store_phone} before ordering to arrange <strong>gluten-free mud cakes</strong> or <strong>vegan celebration cakes</strong>. Our Greenway kitchen handles dairy, eggs, wheat (gluten), soy and tree nuts on shared equipment—please review our <a href=\"{url:allergens}\">Allergen Information</a> before ordering for guests with severe allergies, and collect from {store_address} or book Canberra &amp; Queanbeyan delivery at checkout.</p>' WHERE `slug` = 'halal-cakes-canberra' AND MD5(`body`) = '4840ac0274f55b2943080cfeaabf7a07';
UPDATE `pages` SET `body` = '<h2>Custom 100% Halal Wedding, Engagement &amp; Nikah Cakes in Canberra</h2>\n<p>{store_name} designs, bakes and finishes custom single-tier, two-tier and three-tier wedding and engagement cakes from scratch in our Greenway kitchen (established March 2015), with scheduled courier delivery to reception venues across Canberra, Tuggeranong, Yarralumla, Barton, Braddon, Belconnen, Gungahlin and Queanbeyan. Every tier is baked with <strong>100% Halal ingredients</strong>—zero alcohol, no animal shortening, and Halal-suitable fillings—with eggless, vegan and gluten-free tiers available on request.</p>\n<img src=\"{url:assets/img/wedding-tier-guide.svg}\" alt=\"Canberra wedding cake tier sizing chart comparing Single-Tier Engagement Cake (14 to 25 guests), Two-Tier Wedding Cake (35 to 60 guests), and Three-Tier Statement Wedding Cake (75 to 120+ guests)\" width=\"960\" height=\"360\">\n<h2>Wedding Cake Tiers, Guest Counts &amp; Recommended Booking Notice</h2>\n<table>\n<thead><tr><th scope=\"col\">Tier Configuration</th><th scope=\"col\">Approximate Guests (Coffee Portions)</th><th scope=\"col\">Recommended Notice</th><th scope=\"col\">Fulfilment &amp; Venue Options</th></tr></thead>\n<tbody>\n<tr><td><strong>Single-Tier Tall Cake</strong></td><td>14 – 25 guests</td><td>5 – 7 days (minimum {custom_lead_days} days)</td><td>Greenway pickup or Canberra delivery</td></tr>\n<tr><td><strong>Two-Tier Wedding / Engagement Cake</strong></td><td>35 – 60 guests</td><td>2 – 4 weeks</td><td>Scheduled Canberra &amp; Queanbeyan venue delivery</td></tr>\n<tr><td><strong>Three-Tier Statement Wedding Cake</strong></td><td>75 – 120+ guests</td><td>4 – 8+ weeks (book early for Oct–Apr peak season)</td><td>Scheduled Canberra &amp; winery/hotel venue delivery</td></tr>\n<tr><td><strong>Kitchen Cutting Cakes + Profiterole Towers</strong></td><td>20 – 100+ extra serves</td><td>1 – 2 weeks</td><td>Pair a display tier with <a href=\"{url:shop/mud-cakes}\">Full mud cakes</a> or <a href=\"{url:cakes/profiterole-tower}\">Profiterole Towers</a></td></tr>\n</tbody>\n</table>\n<h2>Most Popular Wedding Sponge Flavours &amp; Decorative Styles</h2>\n<p>Each tier in a multi-tier wedding cake can be baked in a different flavour so you can please both traditional and chocolate-loving guests:</p>\n<ul>\n<li><strong>Dense <a href=\"{url:shop/mud-cakes}\">Mud Cake Tiers</a> (Chocolate, White Gold, Marble or Caramel):</strong> Our top recommendation for tall sculpted, smooth-buttercream and multi-tier wedding cakes—moist, rich and structurally rock-solid during transport and reception display.</li>\n<li><strong><a href=\"{url:cakes/red-velvet-cake}\">Red Velvet</a> &amp; Spiced Carrot Tiers:</strong> Striking slice contrast layered with smooth cream cheese or vanilla buttercream.</li>\n<li><strong>Light <a href=\"{url:shop/tortes}\">European Sponge Tortes</a>:</strong> Ideal for single-tier engagement parties, Nikah lunches and bridal showers where guests prefer airy sponge and fresh cream.</li>\n<li><strong>Finishes:</strong> Smooth ivory buttercream, vintage Lambeth piping, textured palette-knife waves, semi-naked rustic finishes, gold leaf accents, macarons and fresh florals matched to your florist\'s palette.</li>\n</ul>\n<h2>How Quotes, Deposits &amp; Tasting Slices Work</h2>\n<ol>\n<li><strong>Share your wedding details:</strong> Send your reception date, venue suburb, approximate guest count, preferred flavours and 1–2 inspiration photos via our <a href=\"{url:custom-cakes}?occasion=Wedding#quote\">wedding quote form</a> (or pick a design from our <a href=\"{url:custom-cake-gallery}\">custom cake gallery</a>).</li>\n<li><strong>Sample flavours beforehand:</strong> Want to taste sponges with your partner before locking in tiers? Order a Midi cake or visit our counter at {store_address} to try our house mud cakes, velvet cakes and tortes.</li>\n<li><strong>Lock in your date online:</strong> We email an itemised quote; accept online with a 50% booking deposit to reserve your weekend baking and delivery slot, or call our Greenway team on {store_phone}.</li>\n</ol>' WHERE `slug` = 'wedding-cakes-canberra' AND MD5(`body`) = 'b7dd540bcc00fd6c03fcb596e7c4431c';
UPDATE `pages` SET `body` = '<h2>Fresh Birthday Cakes in Canberra — Ready in {min_lead_hours} Hours or Custom-Designed</h2>\n<p>At {store_name} in Greenway, Tuggeranong, we bake fresh birthday cakes every day from scratch using <strong>100% Halal ingredients</strong>—starting from <strong>$34.95 for a Midi cake (serves ~8)</strong> and <strong>$44.95 for a Full birthday cake (serves ~14)</strong>, with a <strong>free custom birthday message</strong> piped on top of every celebration cake. Order a menu favourite online with {min_lead_hours} hours notice, or send us a photo for a custom kids\' or milestone birthday cake.</p>\n<img src=\"{url:assets/img/cake-serving-guide.svg}\" alt=\"Canberra birthday cake size and serving guide: Half Cheesecake serves 6, Midi Birthday Cake serves 8, Full Cheesecake serves 12, Full Birthday Cake serves 14, XL Rainbow Torte serves 20\" width=\"960\" height=\"340\">\n<h2>Compare Ready-Made vs. Custom Birthday Cakes in Canberra</h2>\n<table>\n<thead><tr><th scope=\"col\">Birthday Cake Option</th><th scope=\"col\">Servings</th><th scope=\"col\">Price Guide</th><th scope=\"col\">Notice Needed</th><th scope=\"col\">Top Flavours</th></tr></thead>\n<tbody>\n<tr><td><strong>Midi Menu Birthday Cake</strong></td><td>~8 guests</td><td>From $34.95 – $59.95</td><td>{min_lead_hours} hours online</td><td><a href=\"{url:cakes/black-forest-torte}\">Black Forest</a>, <a href=\"{url:cakes/chocolate-mud-cake}\">Chocolate Mud</a>, <a href=\"{url:cakes/red-velvet-cake}\">Red Velvet</a></td></tr>\n<tr><td><strong>Full Menu Birthday Cake</strong></td><td>~14 guests</td><td>From $44.95 – $69.95</td><td>{min_lead_hours} hours online</td><td><a href=\"{url:cakes/tiramisu-torte}\">Tiramisu Torte</a>, <a href=\"{url:cakes/treasure-cake}\">Treasure Mud</a>, <a href=\"{url:cakes/white-gold-mud-cake}\">White Gold Mud</a></td></tr>\n<tr><td><strong>XL Kids\' Party Rainbow Torte</strong></td><td>~20 guests</td><td>$69.95 (Large 14: $59.95)</td><td>{min_lead_hours} hours online</td><td><a href=\"{url:cakes/rainbow-torte}\">Six-colour Rainbow Sponge Torte</a></td></tr>\n<tr><td><strong>Custom Kids\' &amp; Milestone Cake</strong></td><td>8 – 100+ guests</td><td>Priced by design quote</td><td>3 – 7 days (min {custom_lead_days} days)</td><td>Edible images (Bluey, Spider-Man, Mario), vintage hearts, number &amp; 2-tier cakes</td></tr>\n</tbody>\n</table>\n<h2>Kids\' Character Cakes, Vintage Heart Cakes &amp; Milestone Designs</h2>\n<p>Planning a 1st, 18th, 21st, 30th or 50th birthday in Canberra? Browse our <a href=\"{url:custom-cake-gallery}\">custom cake gallery</a> and tap <em>Order one like this</em> on any unicorn, soccer pitch, Spider-Man, Bluey, drip-and-macaron or piped vintage heart cake—or upload your own reference photo on our <a href=\"{url:custom-cakes}?occasion=Birthday#quote\">custom cake quote form</a>.</p>\n<h2>Same-Week Orders, Eggless Options &amp; Canberra Delivery</h2>\n<ul>\n<li><strong>Free personalised writing:</strong> Type <em>\"Happy 10th Birthday Leo\"</em> on any cake page before adding to cart.</li>\n<li><strong>Dietary-friendly celebrations:</strong> Every cake uses 100% Halal ingredients (zero alcohol), with eggless, vegan and gluten-free mud cake options available on request—see our <a href=\"{url:allergens}\">allergen guide</a>.</li>\n<li><strong>Greenway pickup or Canberra-wide delivery:</strong> Collect free from {store_address} or select scheduled delivery across Tuggeranong, Woden, Weston Creek, Molonglo Valley, Inner South, Inner North, Belconnen, Gungahlin and Queanbeyan at checkout. Need a birthday cake urgently today? Call {store_phone}.</li>\n</ul>' WHERE `slug` = 'birthday-cakes-canberra' AND MD5(`body`) = '68a16b66e5ec533f472c0d1d07d35637';
UPDATE `pages` SET `body` = '<h2>Baby Shower, Gender Reveal &amp; First Birthday Cakes in Canberra</h2>\n<p>{store_name} bakes custom baby shower cakes, pink-or-blue hidden sponge gender reveal cakes, Aqiqah, naming-day, christening and first birthday cakes from scratch in our Greenway kitchen using <strong>100% Halal ingredients</strong>. Because our entire kitchen is 100% alcohol-free and Halal, expectant mums, grandparents, children and extended family can all share the same centrepiece with complete peace of mind.</p>\n<h2>Compare Baby Shower &amp; Gender Reveal Cake Options</h2>\n<table>\n<thead><tr><th scope=\"col\">Celebration Style</th><th scope=\"col\">How It Is Made</th><th scope=\"col\">Typical Guests</th><th scope=\"col\">Recommended Notice</th></tr></thead>\n<tbody>\n<tr><td><strong>Hidden-Colour Gender Reveal Cake</strong></td><td>Neutral white/cream buttercream outside; tinted pink or blue sponge or cream revealed on the first cut</td><td>12 – 30 guests</td><td>4 – 7 days (minimum {custom_lead_days} days)</td></tr>\n<tr><td><strong>Pastel &amp; Teddy Baby Shower Cake</strong></td><td>Single-tier tall or vintage piped heart cake in sage, butter yellow, blush, sky blue or neutral florals</td><td>14 – 35 guests</td><td>5 – 7 days</td></tr>\n<tr><td><strong>Two-Tier Christening, Aqiqah or 1st Birthday</strong></td><td>Sturdy <a href=\"{url:shop/mud-cakes}\">mud cake</a> or <a href=\"{url:shop/velvet-cakes}\">velvet</a> tiers with custom name topper, rosettes or fondant details</td><td>35 – 60+ guests</td><td>2 – 3 weeks</td></tr>\n<tr><td><strong>Last-Minute Ready-Made Cake + Message</strong></td><td>Menu <a href=\"{url:shop/tortes}\">torte</a>, mud cake or <a href=\"{url:cakes/profiterole-tower}\">Profiterole Tower</a> with free piped baby message</td><td>8 – 20 guests</td><td>{min_lead_hours} hours online</td></tr>\n</tbody>\n</table>\n<h2>How Secret Gender Reveal Orders Work (Keep It a Surprise!)</h2>\n<p>Want the baby\'s gender to surprise both parents too? Have your ultrasound envelope dropped into our shop at {store_address}, or ask a trusted friend or sibling to email the result with your quote reference—our pastry team will bake the hidden pink or blue interior while keeping the outside completely neutral in white buttercream, gold leaf or pastel clouds.</p>\n<h2>Dietary Options, Greenway Pickup &amp; Canberra Delivery</h2>\n<ul>\n<li><strong>100% Halal, zero alcohol &amp; pregnancy-conscious handling:</strong> Baked fresh to order with pasteurised Australian dairy; keep cream and buttercream cakes refrigerated at 2–5°C until serving.</li>\n<li><strong>Eggless, vegan &amp; gluten-free requests:</strong> Call {store_phone} before ordering so we can tailor sponge and frosting options—and check our <a href=\"{url:allergens}\">allergen information</a>.</li>\n<li><strong>Easy ordering:</strong> <a href=\"{url:custom-cakes}?occasion=Baby%20shower#quote\">Send your theme and photo for a quote</a>, or <a href=\"{url:shop}\">order a ready-made cake online</a> with {min_lead_hours} hours notice for pickup in Greenway or delivery across Canberra and Queanbeyan.</li>\n</ul>' WHERE `slug` = 'baby-shower-cakes-canberra' AND MD5(`body`) = '27c54ee47ac947c28920d884c63dcd57';

-- FAQ accuracy & answer-engine fan-out expansions
UPDATE `faqs` SET `answer` = '<p>Order menu cakes online at least <strong>{min_lead_hours} hours</strong> ahead. For custom birthday and celebration cakes, please allow <strong>3 to 7 days</strong> (minimum {custom_lead_days} days), and for two- or three-tier wedding cakes we recommend booking <strong>2 to 8+ weeks</strong> ahead—especially for spring and autumn weekends.</p>' WHERE `question` = 'How far in advance should I order?' AND MD5(`answer`) = '11cd74ddeb89e1f30dc9195cfae11651';
UPDATE `faqs` SET `answer` = '<p>Yes — we deliver fresh cakes across all Canberra districts (Tuggeranong, Woden, Weston Creek, Molonglo Valley, Inner South, Inner North, Belconnen and Gungahlin — postcodes 2600–2620 and 2900–2914) and Queanbeyan. Simply choose <strong>Delivery</strong> at online checkout, enter your address and preferred time window, and our Greenway team will email your confirmed delivery window. For outer-region venues, call {store_phone}.</p>' WHERE `question` = 'Do you deliver?' AND MD5(`answer`) = '53a369a6e5a653f1f77f93d7a2ab7375';
UPDATE `faqs` SET `answer` = '<p>Yes — <strong>100% of the cakes, tortes, mud cakes, velvet cakes, cheesecakes and profiterole towers</strong> baked in our Greenway kitchen use 100% Halal ingredients, with zero alcohol or liqueurs, no animal shortening, and only Halal-suitable gelatine and vanilla flavourings.</p>' WHERE `question` = 'Are your cakes Halal?' AND MD5(`answer`) = '937eff2b4460a4dd13e7afc11e44f7cd';
UPDATE `faqs` SET `answer` = '<p>Yes, on request. Eligible cakes offer an <strong>Eggless</strong> checkbox directly on the product page, and we also bake gluten-free mud cakes and vegan celebration cakes by arrangement—please call {store_phone} before ordering and read our <a href=\"{url:allergens}\">allergen information</a> regarding shared-kitchen traces.</p>' WHERE `question` = 'Do you make gluten-free, eggless or vegan cakes?' AND MD5(`answer`) = '7c920e38d8c758cecdc3f628a84eeff1';
INSERT IGNORE INTO `faqs` (`category`, `question`, `answer`, `is_active`, `sort_order`) VALUES ('Ordering', 'How many people do Midi, Half and Full cakes serve?', '<p>Our <strong>Half cheesecakes serve about 6</strong> (from $22.95), <strong>Midi celebration cakes serve about 8</strong> (from $34.95), <strong>Full cheesecakes serve about 12</strong> (from $39.95), and <strong>Full tortes, mud cakes and velvet cakes serve about 14</strong> (from $44.95). For larger crowds, our <a href=\"{url:cakes/rainbow-torte}\">XL Rainbow Torte</a> serves ~20, <a href=\"{url:cakes/profiterole-tower}\">Profiterole Towers</a> serve 10–18, and <a href=\"{url:custom-cakes}\">custom tiered cakes</a> serve up to 120+ guests.</p>', 1, 16);
INSERT IGNORE INTO `faqs` (`category`, `question`, `answer`, `is_active`, `sort_order`) VALUES ('Pickup and delivery', 'How should I transport and store my cake in Canberra?', '<p>Place the cake box flat in your car\'s front passenger footwell (never on a sloped seat) with air-conditioning running. Refrigerate fresh cream tortes, cheesecakes, carrot cake, red velvet and pavlova at <strong>2–5°C</strong> and enjoy within <strong>2 to 3 days</strong>. Let dense mud cakes rest at room temperature for 30 minutes before slicing.</p>', 1, 17);
INSERT IGNORE INTO `faqs` (`category`, `question`, `answer`, `is_active`, `sort_order`) VALUES ('Custom cakes', 'Do you make tiered wedding cakes and deliver to Canberra venues?', '<p>Yes — we bake custom 1-tier, 2-tier and 3-tier 100% Halal <a href=\"{url:wedding-cakes-canberra}\">wedding, engagement and Nikah cakes</a> in Greenway and offer scheduled courier delivery to Canberra and Queanbeyan reception venues. Send your date, guest count and inspiration photo on our <a href=\"{url:custom-cakes}\">custom cake form</a> to receive an itemised quote, reserved online with a 50% deposit.</p>', 1, 18);

-- Bespoke, sensory, non-templated descriptions for all 34 starter cakes
UPDATE `products` SET `description` = '<p>Our <strong>Black Forest Torte Canberra</strong> customers return for year after year layers tender dark chocolate sponge with lightly sweetened whipped vanilla cream and juicy sour cherries, finished with curls of dark chocolate around the crown and cream rosettes. Unlike traditional European versions made with kirsch, our Greenway recipe is <strong>100% alcohol-free and 100% Halal</strong>, using cherry compote syrup so children and every guest at the table can share a slice.</p>\n<p>The balance of bittersweet cocoa crumb, tart cherries and cloud-light dairy cream keeps every forkful refreshing rather than heavy. Choose the <strong>Midi (serves 8)</strong> for a family birthday dinner or the <strong>Full (serves 14)</strong> for larger celebrations, with a free piped birthday or anniversary message included on top.</p>\n<h3>Serving, Dietary Notes &amp; Canberra Ordering</h3>\n<ul>\n<li><strong>Storage:</strong> Keep refrigerated at 2–5°C and serve chilled within 2–3 days.</li>\n<li><strong>Dietary requests:</strong> Ask our bakers on {store_phone} about eggless, vegan or gluten-free torte options.</li>\n<li><strong>Pickup &amp; delivery:</strong> Order online with {min_lead_hours} hours notice for free pickup at {store_address} or delivery across Canberra and Queanbeyan.</li>\n</ul>' WHERE `slug` = 'black-forest-torte' AND MD5(`description`) = 'd7f966f28e7cb3b0d5839cf2bcf18c37';
UPDATE `products` SET `description` = '<p>Silky, feather-light and gently sweet, our <strong>Mousse Torte Canberra</strong> centrepiece pairs delicate sponge layers with an aerated chocolate-and-cream mousse filling and a smooth piped cream finish. Because the mousse is whipped for lift rather than dense ganache weight, it slices effortlessly after a rich roast or banquet dinner without feeling heavy.</p>\n<p>Baked fresh in our Greenway patisserie kitchen using <strong>100% Halal ingredients</strong>—including Halal-suitable setting agents, zero alcohol and fresh Australian cream—this Full-size torte generously <strong>serves 14 guests</strong> and includes complimentary piped lettering on top for birthdays, farewells or family gatherings.</p>\n<h3>Serving Suggestions &amp; Local Fulfilment</h3>\n<ul>\n<li><strong>Clean slicing tip:</strong> Keep chilled at 2–5°C right until serving and dip your knife in warm water between cuts to keep the mousse layers sharp.</li>\n<li><strong>Pairings:</strong> Lovely alongside espresso, peppermint tea or fresh berries from our <a href=\"{url:shop/tortes}\">European torte range</a>.</li>\n<li><strong>How to order:</strong> Book online at least {min_lead_hours} hours ahead for Greenway pickup at {store_address} or courier delivery across Canberra and Queanbeyan, or call {store_phone} for dietary enquiries.</li>\n</ul>' WHERE `slug` = 'mousse-torte' AND MD5(`description`) = 'fa19d638a7c10e65fb50070f37385e2a';
UPDATE `products` SET `description` = '<p>Bright, fruity and unmistakably fresh, our <strong>Strawberry Torte Canberra</strong> favourite layers soft golden vanilla sponge with clouds of whipped continental cream and sweet strawberries. Every bite contrasts airy house-baked sponge against cool dairy cream and berry tang, making it a go-to choice for spring birthdays, bridal showers, Mother\'s Day lunches and sunny Canberra courtyard gatherings.</p>\n<p>Prepared daily from scratch in our Greenway shop with <strong>100% Halal ingredients</strong> (zero alcohol, no animal shortening, Halal-suitable vanilla and glaze), it comes in both <strong>Midi (serves 8)</strong> and <strong>Full (serves 14)</strong> sizes—with your custom celebration message piped free on top.</p>\n<h3>Storage, Dietary Options &amp; Pickup or Delivery</h3>\n<ul>\n<li><strong>Freshness:</strong> Because we use real whipped cream and strawberries, store flat in the refrigerator at 2–5°C and enjoy within 48–72 hours.</li>\n<li><strong>Eggless or custom requests:</strong> Call our Tuggeranong bakers on {store_phone} before ordering to discuss eggless sponge or custom berry decorations.</li>\n<li><strong>Ordering:</strong> Reserve online with {min_lead_hours} hours notice for pickup at {store_address} or scheduled delivery throughout Canberra and Queanbeyan.</li>\n</ul>' WHERE `slug` = 'strawberry-torte' AND MD5(`description`) = '5249ba21bf7832d36ed4645fcce99ec5';
UPDATE `products` SET `description` = '<p>Inspired by classic Central European patisserie, our <strong>Caramel Torte Canberra</strong> speciality layers light Hungarian-style sponge with velvety chocolate buttercream and crowns the cake with a glossy golden caramel glaze. Where fresh-cream fruit tortes lean bright and summery, this Full-size torte delivers deeper roasted-sugar caramel warmth balanced by smooth cocoa cream.</p>\n<p>Handcrafted in Greenway since 2015 using <strong>100% Halal ingredients</strong> with zero alcohol, the Full cake <strong>serves 14 guests</strong> comfortably (or up to 18 smaller coffee fingers) and includes free piped writing for milestone birthdays, Father\'s Day dinners, office shouts and anniversaries.</p>\n<h3>Serving &amp; Canberra Delivery Details</h3>\n<ul>\n<li><strong>Texture tip:</strong> Keep refrigerated at 2–5°C, then stand out of the fridge for 15 minutes before cutting so the chocolate buttercream softens to a silky finish.</li>\n<li><strong>Compare caramel styles:</strong> Prefer a denser fudgy crumb? Try our <a href=\"{url:cakes/caramel-mud-cake}\">Caramel Mud Cake</a> or chilled <a href=\"{url:cakes/caramel-cheesecake}\">Caramel Cheesecake</a>.</li>\n<li><strong>Fulfilment:</strong> Order online {min_lead_hours} hours ahead for pickup at {store_address} or delivery across Canberra and Queanbeyan; call {store_phone} for allergen advice.</li>\n</ul>' WHERE `slug` = 'caramel-torte' AND MD5(`description`) = 'aca5b3f02b732d58029828b7b4c8d924';
UPDATE `products` SET `description` = '<p>Why choose between vanilla and chocolate when your guests can have both in every wedge? Our <strong>Zebra Torte Canberra</strong> crowd-pleaser alternates layers of tender chocolate sponge and golden vanilla sponge with fresh whipped cream, coats the sides in fine chocolate crumbs, and finishes the top with piped cream rosettes.</p>\n<p>When sliced at the table, the striking dark-and-light striped interior makes an instant talking point for family birthdays, school celebrations and office morning teas. Baked fresh in Greenway using <strong>100% Halal ingredients</strong> and zero alcohol, it is available in <strong>Midi (serves 8)</strong> and <strong>Full (serves 14)</strong> sizes with complimentary message writing on top.</p>\n<h3>Good to Know Before Ordering</h3>\n<ul>\n<li><strong>All-ages appeal:</strong> Mild sweetness and dual sponge flavours satisfy picky kids and adults alike without heavy fondant.</li>\n<li><strong>Care &amp; transport:</strong> Carry flat in your car footwell, refrigerate at 2–5°C, and enjoy within 2–3 days.</li>\n<li><strong>Canberra pickup &amp; delivery:</strong> Order online at least {min_lead_hours} hours ahead for free Greenway pickup ({store_address}) or delivery across Canberra and Queanbeyan, or phone {store_phone}.</li>\n</ul>' WHERE `slug` = 'zebra-torte' AND MD5(`description`) = '94dd1e22b77e1ab0273ab11b3846414a';
UPDATE `products` SET `description` = '<p>Crafted for lovers of roasted praline and European nut patisserie, our <strong>Hazelnut Torte Canberra</strong> favourite layers tender house sponge with smooth, aromatic hazelnut cream and nutty chocolate accents. Rich yet buoyant on the fork, it captures the comforting flavour of toasted hazelnuts and cream without overwhelming sweetness—pairing effortlessly with flat whites, Turkish coffee or black tea.</p>\n<p>Baked to order in our Greenway kitchen with <strong>100% Halal ingredients</strong> (zero liqueurs or alcohol), this Full-size celebration torte <strong>serves 14 guests</strong> and comes with your custom message piped free across the top.</p>\n<h3>Allergen, Storage &amp; Ordering Information</h3>\n<ul>\n<li><strong>Tree nut notice:</strong> Contains hazelnuts and dairy, and is baked in our shared Greenway kitchen—see our <a href=\"{url:allergens}\">allergen guide</a> if guests have nut allergies.</li>\n<li><strong>Storage:</strong> Store chilled at 2–5°C and slice with a clean warm knife within 2–3 days of collection.</li>\n<li><strong>Order online:</strong> Place your order {min_lead_hours} hours ahead for timed pickup at {store_address} or delivery anywhere in Canberra and Queanbeyan, or call {store_phone}.</li>\n</ul>' WHERE `slug` = 'hazelnut-torte' AND MD5(`description`) = 'f25e07170816b7709708c3af86272a30';
UPDATE `products` SET `description` = '<p>Pairing dark cocoa richness with juicy red berries, our <strong>Double Choc Strawberry Torte Canberra</strong> bestseller stacks moist chocolate sponge layers with whipped chocolate cream and fresh strawberries. Where a mud cake is dense and fudgy, this double-chocolate torte stays airy and spoon-soft, letting the bright acidity of fresh strawberries lift the cocoa cream in every bite.</p>\n<p>Made fresh daily in our Tuggeranong kitchen using <strong>100% Halal ingredients</strong> and zero alcohol, it is offered in <strong>Midi (serves 8)</strong> for intimate dinners and <strong>Full (serves 14)</strong> for birthday parties, anniversaries, Eid desserts and Valentine\'s celebrations—complete with free custom piped lettering.</p>\n<h3>Storage, Dietary Requests &amp; Fulfilment</h3>\n<ul>\n<li><strong>Chilled freshness:</strong> Keep refrigerated at 2–5°C to protect the fresh strawberries and chocolate dairy cream; best enjoyed within 48–72 hours.</li>\n<li><strong>Custom &amp; eggless options:</strong> Phone {store_phone} before ordering if you require eggless sponge or a custom berry-and-drip presentation.</li>\n<li><strong>Pickup or Canberra delivery:</strong> Book online {min_lead_hours} hours ahead from {store_address} or select scheduled Canberra and Queanbeyan delivery at checkout.</li>\n</ul>' WHERE `slug` = 'double-choc-strawberry-torte' AND MD5(`description`) = '1117aa31ba8e09927b172f27065398d9';
UPDATE `products` SET `description` = '<p>Crunchy chocolate biscuit pieces folded through pillowy cream between soft sponge layers make our <strong>Cookies \'n\' Cream Torte Canberra</strong> party cake an unmistakable hit with kids, teens and Oreo-loving adults. Crowned with piped cream swirls and crisp chocolate sandwich biscuits, it delivers nostalgic cookies-and-milk flavour in a light bakery-fresh torte format.</p>\n<p>Baked from scratch in Greenway with <strong>100% Halal ingredients</strong>—zero alcohol and no animal shortening—this generous Full torte <strong>serves 14 party guests</strong> and includes a free piped birthday name or message on top.</p>\n<h3>Party Planning, Storage &amp; Canberra Delivery</h3>\n<ul>\n<li><strong>Great for kids\' &amp; teen birthdays:</strong> Easier to slice and lighter after party food than heavy fondant cakes; add candles or a number topper in your cart.</li>\n<li><strong>Fridge care:</strong> Store chilled at 2–5°C in its flat bakery box and enjoy within 2–3 days.</li>\n<li><strong>Easy online booking:</strong> Order at least {min_lead_hours} hours in advance for pickup at {store_address} or delivery across Canberra and Queanbeyan. Questions? Call {store_phone}.</li>\n</ul>' WHERE `slug` = 'cookies-n-cream-torte' AND MD5(`description`) = '7668ff2db8f422cd1decc006e7f9023f';
UPDATE `products` SET `description` = '<p>Clean, timeless and endlessly versatile, our <strong>Vanilla Torte Canberra</strong> classic pairs fragrant golden vanilla sponge layers with freshly whipped continental cream. Because its flavour profile is gentle and pure—free from heavy spices, nuts in the batter or dark cocoa—it is our safest crowd-pleaser for mixed-age family gatherings, toddlers\' birthdays, office farewells and school celebrations.</p>\n<p>Every Vanilla Torte is baked in house at our Greenway shop using <strong>100% Halal ingredients</strong> (Halal-suitable vanilla, zero alcohol and fresh Australian dairy). Pick <strong>Midi (serves 8)</strong> or <strong>Full (serves 14)</strong>, and type a complimentary birthday or congratulations message before adding to cart.</p>\n<h3>Customisation, Storage &amp; Local Ordering</h3>\n<ul>\n<li><strong>Easy to dress up:</strong> Delicious served with fresh seasonal berries on the side, or <a href=\"{url:custom-cakes}\">request a custom decorated vanilla sponge</a> with pastel piping or an edible image.</li>\n<li><strong>Storage:</strong> Refrigerate at 2–5°C and transport flat on your car floor; best within 2–3 days.</li>\n<li><strong>Pickup &amp; delivery:</strong> Ready in {min_lead_hours} hours for Greenway pickup ({store_address}) or delivery across Canberra and Queanbeyan; call {store_phone} for eggless options.</li>\n</ul>' WHERE `slug` = 'vanilla-torte' AND MD5(`description`) = '963eea8e076d743dd9c709bdec856478';
UPDATE `products` SET `description` = '<p>One of our highest-rated customer favourites since 2015, our <strong>Tiramisu Torte Canberra</strong> speciality soaks tender sponge layers in bold espresso coffee, layers them with luscious mascarpone-style tiramisu cream, and finishes the crown with a generous dusting of fine dark cocoa. Crucially, we craft it with <strong>zero Marsala, zero coffee liqueur and 100% Halal ingredients</strong>—delivering authentic Italian café flavour that everyone at your table can enjoy.</p>\n<p>Balanced between aromatic roasted espresso bitterness and cool velvety cream, this Full-size torte <strong>serves 14 guests</strong> and includes optional free piped lettering on top for birthdays, graduations and dinner parties.</p>\n<h3>Why Canberra Coffee Lovers Rate It Highly</h3>\n<ul>\n<li><strong>Not overly sweet:</strong> Real coffee infusion keeps the finish grown-up, clean and light after an evening meal.</li>\n<li><strong>Storage:</strong> Keep refrigerated at 2–5°C until the moment you slice; flavours meld beautifully over the first 24–48 hours.</li>\n<li><strong>Fast online ordering:</strong> Reserve at least {min_lead_hours} hours ahead for free pickup at {store_address} or scheduled courier delivery across Canberra and Queanbeyan, or call {store_phone}.</li>\n</ul>' WHERE `slug` = 'tiramisu-torte' AND MD5(`description`) = '1a654fa6c2898965696c3e7ff1ef5c66';
UPDATE `products` SET `description` = '<p>Cut the first wedge and reveal vibrant ribbons of bright rainbow sponge stacked high between smooth white cream—our <strong>Rainbow Torte Canberra</strong> party cake is built for gasps around the birthday table. Unlike dense buttercream rainbow cakes that can feel heavy for young children, our European-style sponge stays soft, colourful and light with fresh whipped cream rosettes.</p>\n<p>Sized specifically for bigger party guest lists, it comes in <strong>Large (serves 14)</strong> and our generous <strong>XL party size (serves 20)</strong>—baked fresh in Greenway using <strong>100% Halal ingredients</strong>, Halal-suitable food colours and zero alcohol, with your child\'s name and age piped free on top.</p>\n<h3>Kids\' Party Sizing, Care &amp; Canberra Delivery</h3>\n<ul>\n<li><strong>Built for party crowds:</strong> The XL 20-serve torte comfortably feeds a whole classroom or family park gathering (keep chilled until cutting!).</li>\n<li><strong>Want a character topper too?</strong> Pair with candles at checkout or <a href=\"{url:custom-cakes}\">enquire about a custom Bluey, Unicorn or Mario design</a>.</li>\n<li><strong>Pickup &amp; delivery:</strong> Order online {min_lead_hours} hours ahead for pickup at {store_address} or delivery across Canberra and Queanbeyan; call {store_phone} with dietary questions.</li>\n</ul>' WHERE `slug` = 'rainbow-torte' AND MD5(`description`) = 'a1832e2955c5a436b2ba650eaa9a4ef0';
UPDATE `products` SET `description` = '<p>Modelled on the beloved European <em>Bienenstich</em> (bee-sting cake), our <strong>Honey-Bee Torte Canberra</strong> baker\'s favourite stacks three fragrant honey-infused sponge layers filled generously with fresh continental cream and smooth vanilla custard. Floral honey warmth in the crumb meets cool, creamy custard without heavy icing sugar—making it a standout choice for grandparents\' birthdays, afternoon teas and guests who prefer nuanced European flavours.</p>\n<p>Baked from scratch in our Greenway kitchen with <strong>100% Halal ingredients</strong> and zero alcohol, it is available in <strong>Midi (serves 8)</strong> and <strong>Full (serves 14)</strong> sizes, complete with free piped message writing.</p>\n<h3>Serving, Storage &amp; Ordering Notes</h3>\n<ul>\n<li><strong>Best served chilled:</strong> Store at 2–5°C in the refrigerator so the custard-and-cream layers hold neat, tall slices for 2–3 days.</li>\n<li><strong>Pairings:</strong> Exceptional alongside Earl Grey tea, chai or a mid-morning cappuccino.</li>\n<li><strong>Greenway pickup &amp; Canberra delivery:</strong> Book online with at least {min_lead_hours} hours notice from {store_address} or choose delivery across Canberra and Queanbeyan; call {store_phone} for dietary enquiries.</li>\n</ul>' WHERE `slug` = 'honey-bee-torte' AND MD5(`description`) = 'cdb4a967fe284b28b4654945a20622df';
UPDATE `products` SET `description` = '<p>Named after our bakery itself, the signature <strong>Continental Torte Canberra</strong> locals have celebrated with since March 2015 showcases traditional European sponge craft: delicate house-baked sponge layers brushed for tenderness and filled with our signature continental cream and smooth custard blend. Light on the palate, never cloying, and finished cleanly by hand, it is the quintessential all-occasion celebration cake.</p>\n<p>Every Continental Torte is baked fresh in our Greenway shop using <strong>100% Halal ingredients</strong>—zero alcohol, no animal shortening and Halal-suitable vanilla—in <strong>Midi (serves 8)</strong> and <strong>Full (serves 14)</strong> sizes, with a complimentary piped message on top.</p>\n<h3>When to Pick Our Signature House Torte</h3>\n<ul>\n<li><strong>Ideal for mixed tastes:</strong> When ordering for an office team, extended family or multi-generational birthday where you want universal appeal.</li>\n<li><strong>Care &amp; transport:</strong> Keep level in the car footwell and refrigerate at 2–5°C for up to 3 days.</li>\n<li><strong>Order online:</strong> Reserve {min_lead_hours} hours ahead for free pickup at {store_address} or delivery across Canberra and Queanbeyan, or phone {store_phone} about eggless options.</li>\n</ul>' WHERE `slug` = 'continental-torte' AND MD5(`description`) = '6bbeda3c468cb7742b9fc341f726043c';
UPDATE `products` SET `description` = '<p>Velvety crimson cocoa-kissed sponge meets thick, tangy layers of smooth cream cheese frosting in our customer-favourite <strong>Red Velvet Cake Canberra</strong> centrepiece. Hand-frosted in our Greenway kitchen, the gentle buttermilk-style tang of the cream cheese icing balances the tender red crumb so every forkful tastes plush, rich and clean rather than sugary.</p>\n<p>Baked from scratch with <strong>100% Halal ingredients</strong> (Halal-suitable colours and vanilla, zero alcohol and no animal shortening), our Red Velvet Cake comes in <strong>Midi (serves 8)</strong> and <strong>Full (serves 14)</strong> sizes, with free custom piped writing included for birthdays, anniversaries, engagements and Eid celebrations.</p>\n<h3>Slicing, Storage &amp; Canberra Fulfilment</h3>\n<ul>\n<li><strong>Best serving temperature:</strong> Store refrigerated at 2–5°C, then rest on the bench for 20 minutes before slicing so the velvet crumb and cream cheese frosting soften together.</li>\n<li><strong>Planning a tiered wedding cake?</strong> Red velvet is also available in 2- and 3-tier <a href=\"{url:wedding-cakes-canberra}\">Canberra wedding cakes</a>.</li>\n<li><strong>Pickup or delivery:</strong> Order online {min_lead_hours} hours ahead from {store_address} or book courier delivery across Canberra and Queanbeyan; call {store_phone} for eggless enquiries.</li>\n</ul>' WHERE `slug` = 'red-velvet-cake' AND MD5(`description`) = 'fc7321d5c4b915e87390339d40205e94';
UPDATE `products` SET `description` = '<p>Deeply cocoa-rich, moist and gloriously fudgy, our <strong>Chocolate Mud Cake Canberra</strong> staple is slow-baked in our Greenway ovens and coated in smooth dark chocolate ganache. Unlike airy sponge cakes, true Australian mud cake has a dense, Melt-in-the-mouth crumb that slices into neat party portions and holds up effortlessly during car trips to parks, restaurants and community halls across the ACT.</p>\n<p>Crafted using <strong>100% Halal ingredients</strong> with zero alcohol and no animal shortening, it is available in <strong>Midi (serves 8)</strong> and <strong>Full (serves 14—or up to 20 finger slices)</strong>, including free piped birthday or celebration lettering on top.</p>\n<h3>Serving, Gluten-Free Options &amp; Ordering</h3>\n<ul>\n<li><strong>Baker\'s serving tip:</strong> Refrigerate for storage, then stand at room temperature for 30–45 minutes before cutting with a warm knife so the ganache turns silky and fudge-soft.</li>\n<li><strong>Gluten-free &amp; custom bases:</strong> Gluten-free mud cakes are available by advance request on {store_phone}, and this recipe is our top base for <a href=\"{url:custom-cakes}\">custom themed cakes</a>.</li>\n<li><strong>Fulfilment:</strong> Order online {min_lead_hours} hours ahead for Greenway pickup ({store_address}) or Canberra &amp; Queanbeyan delivery.</li>\n</ul>' WHERE `slug` = 'chocolate-mud-cake' AND MD5(`description`) = '6194b3f18222e0205a691e81a18e76f3';
UPDATE `products` SET `description` = '<p>Smooth, buttery and laced with a warm caramelised white-chocolate note, our <strong>White Gold Mud Cake Canberra</strong> favourite offers all the dense, fudgy indulgence of a traditional mud cake in a golden ivory crumb. Finished with creamy white-chocolate ganache and piped detail, its elegant pale palette makes it a standout choice for engagements, 21st and 30th birthdays, christenings, Aqiqah and bridal showers.</p>\n<p>Every White Gold Mud Cake is baked from scratch in Greenway with <strong>100% Halal ingredients</strong>—zero alcohol and no animal fats—in <strong>Midi (serves 8)</strong> and <strong>Full (serves 14)</strong> sizes, with a complimentary custom message piped on top.</p>\n<h3>Transport, Storage &amp; Custom Styling</h3>\n<ul>\n<li><strong>Sturdy party travel:</strong> Firm mud structure travels cleanly across Canberra suburbs without sliding; bring to room temperature 30 minutes before serving.</li>\n<li><strong>Custom tier favourite:</strong> Frequently chosen for <a href=\"{url:wedding-cakes-canberra}\">tiered wedding cakes</a> and pastel <a href=\"{url:baby-shower-cakes-canberra}\">baby shower cakes</a>.</li>\n<li><strong>Order online:</strong> Book {min_lead_hours} hours ahead for free pickup at {store_address} or delivery across Canberra and Queanbeyan; call {store_phone} about gluten-free mud requests.</li>\n</ul>' WHERE `slug` = 'white-gold-mud-cake' AND MD5(`description`) = 'b4643872324712eba3b7eff1f95ef2d7';
UPDATE `products` SET `description` = '<p>Swirling ribbons of rich dark cocoa batter and golden vanilla mud batter together in the tin, our <strong>Marble Mud Cake Canberra</strong> crowd-pleaser gives every guest two classic mud flavours in a single artistic slice. Coated in glossy chocolate ganache, each cut reveals a unique marbled pattern while keeping the signature dense, moist crumb our Greenway mud cakes are known for.</p>\n<p>Baked fresh using <strong>100% Halal ingredients</strong> with zero alcohol and no animal shortening, it comes in <strong>Midi (serves 8)</strong> for family dinners and <strong>Full (serves 14)</strong> for offices, classrooms and birthday parties—complete with free custom piped writing on top.</p>\n<h3>Why Hosts Pick Marble Mud Cake</h3>\n<ul>\n<li><strong>Solves the chocolate-vs-vanilla debate:</strong> Ideal for workplace morning teas and kids\' parties where half the room wants vanilla and half wants chocolate.</li>\n<li><strong>Serving &amp; storage:</strong> Keeps well refrigerated for up to 4 days; stand at room temperature for 30 minutes before slicing.</li>\n<li><strong>Canberra pickup &amp; delivery:</strong> Order online {min_lead_hours} hours ahead from {store_address} or select scheduled Canberra and Queanbeyan delivery; phone {store_phone} for dietary options.</li>\n</ul>' WHERE `slug` = 'marble-mud-cake' AND MD5(`description`) = '6e8a77a713af7eaa79dbf59f63742ad6';
UPDATE `products` SET `description` = '<p>Slow-baked for deep brown-butter and golden toffee richness, our <strong>Caramel Mud Cake Canberra</strong> indulgence pairs a moist, tender caramel mud crumb with a smooth caramel glaze finish. Less bitter than dark chocolate and warmer than plain vanilla, its buttery Dulce-style sweetness shines alongside hot coffee at autumn and winter celebrations, milestone birthdays and family Sunday roasts.</p>\n<p>Prepared from scratch in our Greenway kitchen with <strong>100% Halal ingredients</strong> (zero alcohol and zero animal shortening), choose <strong>Midi (serves 8)</strong> or <strong>Full (serves 14)</strong> and add your complimentary piped cake message before adding to cart.</p>\n<h3>Serving, Dietary &amp; Delivery Guide</h3>\n<ul>\n<li><strong>Slicing tip:</strong> Let chilled mud slices warm on the bench for 30 minutes before serving so the buttery caramel crumb opens up on the palate.</li>\n<li><strong>Gluten-free &amp; custom options:</strong> Call {store_phone} in advance to enquire about gluten-free mud baking or <a href=\"{url:custom-cakes}\">custom caramel drip cakes</a>.</li>\n<li><strong>Local fulfilment:</strong> Order online with {min_lead_hours} hours notice for pickup at {store_address} or delivery across Canberra and Queanbeyan.</li>\n</ul>' WHERE `slug` = 'caramel-mud-cake' AND MD5(`description`) = '6233b2901df37bd478e5a17b3dc702ca';
UPDATE `products` SET `description` = '<p>Built as an instant party centrepiece, our signature <strong>Treasure Cake Canberra</strong> showstopper starts with our moist, fudgy house mud cake coated in glossy chocolate ganache and crowns the top with a generous bounty of assorted chocolates and sweet treats. There is no need to buy extra toppers—the loaded chocolate crown brings immediate theatre the moment you open the box.</p>\n<p>Handcrafted in Greenway using <strong>100% Halal ingredients</strong> (including 100% Halal confectionery toppings, zero alcohol and no animal fats), it is offered in <strong>Midi (serves 8)</strong> and <strong>Full (serves 14)</strong> sizes with a free piped birthday message nestled on top.</p>\n<h3>Ideal Occasions &amp; Canberra Ordering</h3>\n<ul>\n<li><strong>Favourite for teens &amp; chocoholics:</strong> Especially popular for 13th, 16th, 18th and 21st birthdays, graduation gifts and Father\'s Day celebrations.</li>\n<li><strong>Transport &amp; care:</strong> Dense mud base travels sturdily across Canberra; keep cool in the fridge and rest 30 minutes at room temperature before cutting between the chocolate toppings.</li>\n<li><strong>Pickup or delivery:</strong> Book online {min_lead_hours} hours ahead for pickup at {store_address} or delivery across Canberra and Queanbeyan; call {store_phone} for allergen details.</li>\n</ul>' WHERE `slug` = 'treasure-cake' AND MD5(`description`) = '00f3c571a13c6fe953fa498d6227a6bc';
UPDATE `products` SET `description` = '<p>Rich, velvety and baked until lightly golden over a buttery crushed-biscuit base, our <strong>American Baked Cheesecake Canberra</strong> classic honours authentic New York delicatessen style. Smooth full-bodied cream cheese, eggs and fragrant vanilla bake gently in our Greenway ovens for a dense, satin-smooth wedge with zero sourness or chalkiness.</p>\n<p>Made fresh using <strong>100% Halal ingredients</strong> (zero alcohol and no animal shortening), it comes in two practical sizes: <strong>Half (serves 6)</strong> for a cosy family dinner and <strong>Full (serves 12)</strong> for dinner parties, office morning teas and birthday dessert tables.</p>\n<h3>Serving Ideas &amp; Canberra Pickup or Delivery</h3>\n<ul>\n<li><strong>Dress it up or serve classic:</strong> Delicious plain alongside double espresso, or spoon fresh strawberries, raspberries or warm berry compote over each slice at home.</li>\n<li><strong>Clean wedge tip:</strong> Keep chilled at 2–5°C and wipe a thin knife with hot water between cuts.</li>\n<li><strong>Order online:</strong> Ready in {min_lead_hours} hours for free pickup at {store_address} or scheduled delivery across Canberra and Queanbeyan. Questions? Call {store_phone}.</li>\n</ul>' WHERE `slug` = 'american-baked-cheesecake' AND MD5(`description`) = 'aa42c88256a9cb5ff932cf25376e5644';
UPDATE `products` SET `description` = '<p>Combining dense New York-style oven-baked cream cheese richness with bursts of sweet-tart purple berries, our <strong>Blueberry Baked Cheesecake Canberra</strong> favourite sits on a crisp golden biscuit crumb and finishes with a glossy blueberry topping. The natural berry acidity cuts neatly through the creamy baked filling, making every forkful bright and indulgent.</p>\n<p>Baked in house at our Greenway shop with <strong>100% Halal ingredients</strong> and zero alcohol, choose a <strong>Half cheesecake (serves 6)</strong> for weekend family lunches or a <strong>Full cheesecake (serves 12)</strong> for workplace shouts and celebrations.</p>\n<h3>Baked vs. Chilled Blueberry &amp; Local Ordering</h3>\n<ul>\n<li><strong>Texture comparison:</strong> Prefer a lighter, mousse-set chilled filling instead of dense oven-baked richness? See our <a href=\"{url:cakes/blueberry-cheesecake}\">Blueberry Continental Cheesecake</a>.</li>\n<li><strong>Storage:</strong> Transport flat, refrigerate at 2–5°C, and enjoy within 3 days of pickup.</li>\n<li><strong>Fulfilment:</strong> Book online {min_lead_hours} hours ahead for Greenway pickup ({store_address}) or delivery across Canberra and Queanbeyan, or phone {store_phone}.</li>\n</ul>' WHERE `slug` = 'blueberry-baked-cheesecake' AND MD5(`description`) = '538a0c19ba3e9b5197a8ade3f2c674c5';
UPDATE `products` SET `description` = '<p>Artfully swirled with dark chocolate ribbons through velvety vanilla cream cheese before slow oven baking, our <strong>Marble Baked Cheesecake Canberra</strong> dessert looks as striking on a cake stand as it tastes. Resting on a crunchy biscuit crust, each dense, custard-smooth wedge balances tangy baked cream cheese with mellow cocoa depth.</p>\n<p>Handcrafted in our Tuggeranong kitchen using <strong>100% Halal ingredients</strong>—zero alcohol and no animal shortening—it is available in <strong>Half (serves 6)</strong> and <strong>Full (serves 12)</strong> sizes to suit everything from a four-person dinner party to a twelve-guest celebration.</p>\n<h3>Pairing, Storage &amp; Canberra Delivery</h3>\n<ul>\n<li><strong>After-dinner winner:</strong> Pairs effortlessly with black coffee, hot chocolate or fresh cherries without needing extra cream on the side.</li>\n<li><strong>Care:</strong> Keep refrigerated at 2–5°C and slice chilled with a warm blade for crisp marble contrast.</li>\n<li><strong>How to order:</strong> Reserve online with {min_lead_hours} hours notice for free pickup at {store_address} or courier delivery across Canberra and Queanbeyan; call {store_phone} for allergen checks.</li>\n</ul>' WHERE `slug` = 'marble-baked-cheesecake' AND MD5(`description`) = 'b07ab400d13cfd6790a56199640de98a';
UPDATE `products` SET `description` = '<p>Bring sunny fruit brightness to any Canberra table with our <strong>Tropical Baked Cheesecake Canberra</strong> crowd-pleaser: a rich, oven-baked cream cheese filling on a golden biscuit base crowned with a vibrant tropical fruit topping. Sweet mango, pineapple and passionfruit notes lift the creamy baked custard, bridging classic cheesecake indulgence with refreshing summer flavour.</p>\n<p>Baked fresh in Greenway using <strong>100% Halal ingredients</strong> and zero alcohol, pick a <strong>Half size (serves 6)</strong> for a small family treat or a <strong>Full size (serves 12)</strong> for barbecues, Eid lunches and office farewells.</p>\n<h3>Storage &amp; Canberra Ordering Details</h3>\n<ul>\n<li><strong>Storage &amp; shelf life:</strong> Keep chilled in the refrigerator at 2–5°C and enjoy within 2–3 days while the fruit glaze is glossy and vibrant.</li>\n<li><strong>Compare styles:</strong> Looking for an even lighter mousse-style citrus/fruit finish? Explore our <a href=\"{url:cakes/passionfruit-cheesecake}\">Passionfruit Continental Cheesecake</a>.</li>\n<li><strong>Pickup or delivery:</strong> Order online {min_lead_hours} hours ahead from {store_address} or book delivery across Canberra and Queanbeyan; call {store_phone} with any ingredient questions.</li>\n</ul>' WHERE `slug` = 'tropical-baked-cheesecake' AND MD5(`description`) = 'c436f0338094dc17abaee15722eacc4b';
UPDATE `products` SET `description` = '<p>Rich roasted hazelnut meets velvety oven-baked cream cheese in our <strong>Hazelnut Baked Cheesecake Canberra</strong> dessert, baked gently on a crisp biscuit base in our Greenway kitchen. Nutty praline-chocolate notes weave through the dense, creamy cheesecake interior, making it a favourite winter warmer and sophisticated alternative to traditional birthday sponge.</p>\n<p>Prepared from scratch with <strong>100% Halal ingredients</strong>—zero alcohol and no animal shortening—it comes in <strong>Half (serves 6)</strong> and <strong>Full (serves 12)</strong> options to match intimate dinners and larger dessert spreads alike.</p>\n<h3>Allergen Notes, Slicing &amp; Fulfilment</h3>\n<ul>\n<li><strong>Allergen note:</strong> Contains tree nuts (hazelnuts), dairy, eggs and gluten—please review our <a href=\"{url:allergens}\">allergen guide</a> when catering for guests.</li>\n<li><strong>Serving tip:</strong> Refrigerate at 2–5°C; take out 10–15 minutes before serving alongside espresso for peak roasted-nut aroma.</li>\n<li><strong>Canberra pickup &amp; delivery:</strong> Book online at least {min_lead_hours} hours ahead for pickup at {store_address} or delivery across Canberra and Queanbeyan, or phone {store_phone}.</li>\n</ul>' WHERE `slug` = 'hazelnut-baked-cheesecake' AND MD5(`description`) = '5e081cb499016351dc070b3a197b9967';
UPDATE `products` SET `description` = '<p>Cool, airy and dotted throughout with crisp chocolate chips, our <strong>Choc Chip Cheesecake Canberra</strong> favourite is made in the light continental no-bake style on a buttery biscuit crumb. Every spoonful contrasts cloud-soft chilled cream cheese mousse against tiny snaps of dark chocolate—giving kids and chocolate fans a refreshing dessert that never feels heavy.</p>\n<p>Crucially, our Greenway kitchen sets every continental cheesecake exclusively with <strong>100% Halal-suitable ingredients</strong> (zero porcine gelatine, zero alcohol and no animal fats). Available in <strong>Half (serves 6)</strong> and <strong>Full (serves 12)</strong> sizes.</p>\n<h3>Chilled Care &amp; Local Canberra Ordering</h3>\n<ul>\n<li><strong>Keep cold until serving:</strong> Continental cheesecakes have a delicate mousse-like set—carry flat with car air-con on and store at 2–5°C for up to 3 days.</li>\n<li><strong>Great for mixed dessert tables:</strong> Pair a Half Choc Chip Cheesecake with a Half <a href=\"{url:cakes/strawberry-cheesecake}\">Strawberry Cheesecake</a> to offer two flavours for 12 guests!</li>\n<li><strong>Pickup or delivery:</strong> Order online {min_lead_hours} hours ahead from {store_address} or choose Canberra and Queanbeyan delivery at checkout; call {store_phone}.</li>\n</ul>' WHERE `slug` = 'choc-chip-cheesecake' AND MD5(`description`) = 'bfc66a8e71e97cb49558c74d3f664ed0';
UPDATE `products` SET `description` = '<p>Smooth, chilled and crowned with a silky golden caramel mirror, our <strong>Caramel Cheesecake Canberra</strong> continental dessert pairs an airy, whipped cream cheese filling with a crisp biscuit base. Unlike oven-baked caramel cakes, this continental-style cheesecake stays cool and mousse-light on the spoon—ideal after a generous family roast, curry banquet or barbecue.</p>\n<p>Handcrafted in our Greenway shop using <strong>100% Halal ingredients</strong>—including Halal-suitable setting agents, zero alcohol and fresh Australian dairy—choose between <strong>Half (serves 6)</strong> and <strong>Full (serves 12)</strong> sizes.</p>\n<h3>Serving Suggestions &amp; Canberra Delivery</h3>\n<ul>\n<li><strong>Storage:</strong> Keep refrigerated at 2–5°C right up to serving time so the caramel glaze and mousse filling slice cleanly.</li>\n<li><strong>Mix-and-match tip:</strong> Hosting a grazing table? Combine Half sizes across Caramel, <a href=\"{url:cakes/passionfruit-cheesecake}\">Passionfruit</a> and <a href=\"{url:cakes/choc-chip-cheesecake}\">Choc Chip</a> for effortless variety.</li>\n<li><strong>Fast online booking:</strong> Order at least {min_lead_hours} hours ahead for free Greenway pickup ({store_address}) or delivery across Canberra and Queanbeyan; phone {store_phone}.</li>\n</ul>' WHERE `slug` = 'caramel-cheesecake' AND MD5(`description`) = '7af7164ee8ce1fa7d22bcf16a4f96a13';
UPDATE `products` SET `description` = '<p>One of our bestselling chilled desserts, this <strong>Strawberry Cheesecake Canberra</strong> favourite tops a light, mousse-set continental cream cheese filling with sweet ruby strawberry glaze over a golden biscuit crumb. Cool, fruity and delicate, it delivers classic strawberries-and-cream appeal in a sliceable cheesecake that suits both children\'s dinners and adult afternoon teas.</p>\n<p>Prepared fresh in our Greenway kitchen with <strong>100% Halal ingredients</strong>—strictly zero pork gelatine, zero alcohol and no animal shortening—it is available in <strong>Half (serves 6)</strong> and <strong>Full (serves 12)</strong> sizes.</p>\n<h3>Why Canberra Families Love Our Continental Style</h3>\n<ul>\n<li><strong>Light after big meals:</strong> Refreshing whipped texture makes it effortless to enjoy after festive Eid lunches, Sunday roasts and summer barbecues.</li>\n<li><strong>Fridge care:</strong> Transport flat and keep chilled at 2–5°C until the moment you cut; best within 2–3 days.</li>\n<li><strong>Order online:</strong> Ready with {min_lead_hours} hours notice for pickup at {store_address} or courier delivery across Canberra and Queanbeyan. Call {store_phone} for allergen advice.</li>\n</ul>' WHERE `slug` = 'strawberry-cheesecake' AND MD5(`description`) = 'e9dd37ed287dafcd1d9b9e293687fb9e';
UPDATE `products` SET `description` = '<p>Bright tropical tang meets cool, airy creaminess in our <strong>Passionfruit Cheesecake Canberra</strong> staple: a light continental-style set cheesecake on a crisp biscuit base, finished with golden passionfruit topping speckled with real seeds. That unmistakable Australian passionfruit zing cuts cleanly through the whipped cream cheese beneath, making it a warm-weather standout.</p>\n<p>Made in house at our Greenway patisserie using <strong>100% Halal ingredients</strong> (Halal-suitable setting agents, zero alcohol and zero animal shortening), choose <strong>Half (serves 6)</strong> for small gatherings or <strong>Full (serves 12)</strong> for parties and office morning teas.</p>\n<h3>Serving, Storage &amp; Local Fulfilment</h3>\n<ul>\n<li><strong>Summer &amp; barbecue hero:</strong> Pairs wonderfully with fresh mango, berries or iced tea on sunny Canberra afternoons.</li>\n<li><strong>Chilled handling:</strong> Store flat in your fridge at 2–5°C and serve straight from cold within 2–3 days.</li>\n<li><strong>Greenway pickup &amp; delivery:</strong> Book online {min_lead_hours} hours ahead for pickup at {store_address} or scheduled delivery across Canberra and Queanbeyan; call {store_phone}.</li>\n</ul>' WHERE `slug` = 'passionfruit-cheesecake' AND MD5(`description`) = '8b7ede52bc9959f0e7b6d960c4c8da23';
UPDATE `products` SET `description` = '<p>Crisp, zesty and wonderfully refreshing, our <strong>Tangy Lemon Cheesecake Canberra</strong> continental cheesecake pairs a feather-light set cream cheese filling on a golden biscuit crust with a bright lemon finish. Designed for guests who prefer citrus snap over heavy chocolate or caramel, it acts as an effortless palate cleanser after rich savoury courses.</p>\n<p>Every Tangy Lemon Cheesecake is prepared fresh in Greenway using <strong>100% Halal ingredients</strong>—Halal-suitable gelatine/setting agents, zero alcohol and no animal fats—in convenient <strong>Half (serves 6)</strong> and <strong>Full (serves 12)</strong> sizes.</p>\n<h3>When to Choose Tangy Lemon Cheesecake</h3>\n<ul>\n<li><strong>Ideal for citrus fans:</strong> Our brightest, least-sweet cheesecake option—great for afternoon tea, seafood lunches and summer dinners.</li>\n<li><strong>Care &amp; slicing:</strong> Keep refrigerated at 2–5°C until serving and wipe your blade clean between wedges.</li>\n<li><strong>Pickup or Canberra delivery:</strong> Order online at least {min_lead_hours} hours ahead from {store_address} or select delivery across Canberra and Queanbeyan at checkout; phone {store_phone}.</li>\n</ul>' WHERE `slug` = 'tangy-lemon-cheesecake' AND MD5(`description`) = '02d99547e3eab94dcfed5b37292a6f84';
UPDATE `products` SET `description` = '<p>Cool, mousse-light and crowned with jewel-bright whole blueberry topping, our <strong>Blueberry Cheesecake Canberra</strong> continental cheesecake sits on a buttery biscuit crumb without heavy oven baking. Compared with our denser New York <a href=\"{url:cakes/blueberry-baked-cheesecake}\">Blueberry Baked Cheesecake</a>, this chilled continental style feels airy, gentle and refreshing on warm afternoons or after a hearty family meal.</p>\n<p>Handcrafted in our Greenway kitchen with <strong>100% Halal ingredients</strong>—zero porcine gelatine, zero alcohol and no animal shortening—it is offered in <strong>Half (serves 6)</strong> and <strong>Full (serves 12)</strong> sizes.</p>\n<h3>Storage, Pairing &amp; Canberra Ordering</h3>\n<ul>\n<li><strong>Storage:</strong> Carry flat in an air-conditioned car and keep chilled at 2–5°C in the refrigerator for up to 3 days.</li>\n<li><strong>Great for morning teas:</strong> Easy to portion cleanly on paper plates at workplace shouts and community catch-ups.</li>\n<li><strong>Book online:</strong> Place your order {min_lead_hours} hours ahead for free pickup at {store_address} or scheduled delivery across Canberra and Queanbeyan; call {store_phone}.</li>\n</ul>' WHERE `slug` = 'blueberry-cheesecake' AND MD5(`description`) = 'adf27d852280c9e6b3b32cc9e75b9e2e';
UPDATE `products` SET `description` = '<p>Packed with freshly grated carrot, warm baking spices and a tender, moist crumb, our <strong>Carrot Cake Canberra</strong> morning-tea favourite is finished generously with smooth, tangy cream cheese icing. Neither dry nor overly spiced, it strikes that nostalgic homestyle balance that pairs effortlessly with flat whites, chai lattes and pot-brewed tea.</p>\n<p>Baked from scratch in our Greenway kitchen using <strong>100% Halal ingredients</strong> (zero alcohol and no animal shortening), our Carrot Cake comes in <strong>Midi (serves 8)</strong> and <strong>Full (serves 14)</strong> sizes, with a complimentary piped birthday or thank-you message available on top.</p>\n<h3>Allergen, Storage &amp; Ordering Guide</h3>\n<ul>\n<li><strong>Allergen note:</strong> Please check with our team on {store_phone} or read our <a href=\"{url:allergens}\">allergen information</a> regarding walnuts/tree nuts, gluten, dairy and eggs in our shared Greenway kitchen.</li>\n<li><strong>Storage:</strong> Because of the real cream cheese icing, store refrigerated at 2–5°C and stand at room temperature for 15–20 minutes before slicing.</li>\n<li><strong>Fulfilment:</strong> Order online {min_lead_hours} hours ahead for pickup at {store_address} or delivery across Canberra and Queanbeyan.</li>\n</ul>' WHERE `slug` = 'carrot-cake' AND MD5(`description`) = '20c9d850d9f37d71b07626a33f880c4d';
UPDATE `products` SET `description` = '<p>A true French-patisserie showstopper built in Greenway, our <strong>Profiterole Tower Canberra</strong> centrepiece stacks golden choux pastry puffs filled with cool whipped continental cream and drizzles the entire cone in glossy chocolate. Dramatic on arrival yet effortless to serve—guests simply pluck individual cream puffs straight from the tower without needing cake knives or slicing plates.</p>\n<p>Hand-baked to order with <strong>100% Halal ingredients</strong> (zero alcohol and no animal shortening), choose from four crowd-ready sizes: <strong>20 pieces (serves ~10)</strong>, <strong>25 pieces (serves ~12)</strong>, <strong>30 pieces (serves ~15)</strong> or <strong>35 pieces (serves ~18)</strong>, with free celebration writing included.</p>\n<h3>Events, Transport &amp; Larger Custom Towers</h3>\n<ul>\n<li><strong>Favourite for stand-up events:</strong> Ideal for engagements, milestone birthdays, corporate launches, Eid tables and wedding dessert buffets.</li>\n<li><strong>Need 50+ pieces?</strong> <a href=\"{url:custom-cakes}\">Send a custom quote request</a> for taller wedding or corporate croquembouche-style towers.</li>\n<li><strong>Care &amp; ordering:</strong> Keep refrigerated at 2–5°C and serve on the day of collection for the crispest choux pastry. Order online {min_lead_hours} hours ahead from {store_address} or book Canberra &amp; Queanbeyan delivery; call {store_phone}.</li>\n</ul>' WHERE `slug` = 'profiterole-tower' AND MD5(`description`) = '12617b3a84c96d3b7056206b5db86a03';
UPDATE `products` SET `description` = '<p>Crisp, snowy meringue on the outside, pillowy marshmallow softness in the centre, and crowned generously with freshly whipped cream and vibrant seasonal fruit—our <strong>Pavlova Canberra</strong> celebration dessert is baked fresh in our Greenway ovens for effortless entertaining. Sized generously to <strong>serve about 10 guests</strong>, it brings classic Australian summer and festive charm to family lunches, Christmas tables, Eid banquets and backyard barbecues.</p>\n<p>Prepared with <strong>100% Halal ingredients</strong>, zero alcohol and fresh local dairy, it arrives decorated and ready for the centre of your table.</p>\n<h3>Freshness, Ingredient Notes &amp; Canberra Delivery</h3>\n<ul>\n<li><strong>Best enjoyed fresh:</strong> Keep refrigerated at 2–5°C and serve on the day of pickup (or within 24–48 hours) while the outer meringue shell retains its delicate crunch beneath the cream.</li>\n<li><strong>Wheat &amp; allergen note:</strong> While meringue contains no wheat flour, our Greenway kitchen handles wheat, eggs, dairy, soy and nuts—please read our <a href=\"{url:allergens}\">allergen guide</a> if ordering for coeliac guests.</li>\n<li><strong>Ordering:</strong> Book online {min_lead_hours} hours ahead for pickup at {store_address} or careful courier delivery across Canberra and Queanbeyan; phone {store_phone}.</li>\n</ul>' WHERE `slug` = 'pavlova' AND MD5(`description`) = '639c4841b06a717488bb1b714290d6e5';
UPDATE `products` SET `description` = '<p>Fragrant with bright citrus zest and speckled throughout with nutty blue poppy seeds, our <strong>Orange &amp; Poppy Seed Cake Canberra</strong> tea cake offers a moist, tender crumb finished cleanly for effortless slicing. Lighter than chocolate mud cake and brighter than spiced carrot cake, its sunny orange aroma makes it a staple for Canberra office morning teas, brunch tables, book clubs and thoughtful host gifts.</p>\n<p>Baked from scratch in our Greenway shop using <strong>100% Halal ingredients</strong>—zero alcohol and no animal shortening—it is available in <strong>Midi (serves 8)</strong> and <strong>Full (serves 14)</strong> sizes, with free custom piped writing included if you are gifting or celebrating a birthday.</p>\n<h3>Serving Suggestions &amp; Local Fulfilment</h3>\n<ul>\n<li><strong>Pairings:</strong> Wonderful slightly cool or at room temperature alongside Earl Grey, green tea, long blacks or a dollop of Greek yoghurt and berries.</li>\n<li><strong>Storage:</strong> Store refrigerated in a sealed box and bring to room temperature 20 minutes before serving; stays moist for up to 3 days.</li>\n<li><strong>Greenway pickup &amp; Canberra delivery:</strong> Order online at least {min_lead_hours} hours ahead from {store_address} or choose delivery across Canberra and Queanbeyan, or call {store_phone}.</li>\n</ul>' WHERE `slug` = 'orange-poppy-seed-cake' AND MD5(`description`) = '4c217b1d36515e6960e82d8de9864770';
